package app.studyforge.mobile;

import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.io.*;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.interfaces.RSAPublicKey;
import java.util.*;

public class CoreTest {
    @Test public void pkceMatchesRfc7636() throws Exception {assertEquals("E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM",OAuthSecurity.challenge("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"));assertNotEquals(OAuthSecurity.random(),OAuthSecurity.random());assertTrue(OAuthSecurity.planPermission("openid chatgpt.tokens.use.direct offline_access"));assertFalse(OAuthSecurity.planPermission("openid email"));}
    @Test public void duplicateCallbackParametersRejected() throws Exception {assertEquals("a+b",OAuthSecurity.parseQuery("code=a%2Bb&state=x").get("code"));assertThrows(Exception.class,()->OAuthSecurity.parseQuery("state=a&state=b"));}
    private static String b64(byte[] bytes){return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
    private static byte[] unsigned(BigInteger n){byte[] b=n.toByteArray();return b.length>1&&b[0]==0?Arrays.copyOfRange(b,1,b.length):b;}
    @Test public void idTokenRequiresSignatureIssuerAudienceExpiryAndNonce() throws Exception {
        KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);KeyPair pair=generator.generateKeyPair();RSAPublicKey key=(RSAPublicKey)pair.getPublic();JSONObject jwks=Json.object("keys",Json.array(Json.object("kid","test","kty","RSA","use","sig","n",b64(unsigned(key.getModulus())),"e",b64(unsigned(key.getPublicExponent())))));
        JSONObject claims=Json.object("iss",OAuthSecurity.ISSUER,"aud","client","sub","test-user","exp",2000,"iat",900,"nonce","nonce");String jwt=sign(claims,pair);assertEquals("test-user",OAuthSecurity.verifyIdToken(jwt,jwks,"client","nonce",1000).getString("sub"));assertThrows(Exception.class,()->OAuthSecurity.verifyIdToken(jwt,jwks,"other-client","nonce",1000));assertThrows(Exception.class,()->OAuthSecurity.verifyIdToken(jwt,jwks,"client","wrong-nonce",1000));assertThrows(Exception.class,()->OAuthSecurity.verifyIdToken(jwt,jwks,"client","nonce",2000));String tampered=jwt.substring(0,jwt.lastIndexOf('.')+1)+b64(new byte[256]);assertThrows(Exception.class,()->OAuthSecurity.verifyIdToken(tampered,jwks,"client","nonce",1000));
        JSONObject issuer=Json.copy(claims).put("iss","https://example.invalid");assertThrows(Exception.class,()->OAuthSecurity.verifyIdToken(sign(issuer,pair),jwks,"client","nonce",1000));JSONObject multi=Json.copy(claims).put("aud",Json.array("client","other"));assertThrows(Exception.class,()->OAuthSecurity.verifyIdToken(sign(multi,pair),jwks,"client","nonce",1000));multi.put("azp","client");assertEquals("test-user",OAuthSecurity.verifyIdToken(sign(multi,pair),jwks,"client","nonce",1000).getString("sub"));
    }
    static String sign(JSONObject claims,KeyPair pair) throws Exception {String payload=b64(Json.object("alg","RS256","kid","test").toString().getBytes(StandardCharsets.UTF_8))+"."+b64(claims.toString().getBytes(StandardCharsets.UTF_8));Signature signature=Signature.getInstance("SHA256withRSA");signature.initSign(pair.getPrivate());signature.update(payload.getBytes(StandardCharsets.US_ASCII));return payload+"."+b64(signature.sign());}
    static String event(JSONObject event){return "data: "+event+"\n\n";}
    static String stream(String events) throws Exception {return Sse.read(new ByteArrayInputStream(events.getBytes(StandardCharsets.UTF_8)),m->{});}
    @Test public void sseDoesNotAcceptPartialOrFailedResults() throws Exception {
        String delta=event(Json.object("type","response.output_text.delta","delta","hello"));assertEquals("hello",stream(delta+event(Json.object("type","response.completed","response",new JSONObject()))));assertThrows(IOException.class,()->stream(delta));assertThrows(IOException.class,()->stream(delta+event(Json.object("type","response.incomplete"))));Exception limited=assertThrows(Exception.class,()->stream(delta+event(Json.object("type","response.failed","response",Json.object("error",Json.object("code","subscription_sharing_usage_limit_exceeded"))))));assertTrue(limited.getMessage().contains("구독 사용 한도"));assertThrows(Exception.class,()->stream("data: [DONE]\n\n"));
    }
    @Test public void sseCanReadCompletedOutputAndMultilineEvents() throws Exception {JSONObject complete=Json.object("type","response.completed","response",Json.object("output",Json.array(Json.object("content",Json.array(Json.object("type","output_text","text","done"))))));assertEquals("done",stream(event(complete)));String multi="data: {\"type\":\"response.output_text.delta\",\n"+"data: \"delta\":\"둘\"}\n\n"+event(Json.object("type","response.completed","response",new JSONObject()));assertEquals("둘",stream(multi));}
    static JSONArray sources() throws Exception {return Json.array(Json.object("id","s1","title","notes","role","textbook","text","틸라코이드 막에서 ATP와 NADPH를 생성한다.","images",new JSONArray()));}
    static JSONObject result() throws Exception {JSONObject c=Json.object("source_id","s1","page",1,"quote","틸라코이드 막에서 ATP와 NADPH를 생성한다.");return Json.object("title","생명과학","summary",Json.array(Json.object("title","명반응","text","틸라코이드 막", "source_id","s1","page",1,"quote","틸라코이드 막에서 ATP와 NADPH를 생성한다.")),"directives",new JSONArray(),"questions",Json.array(Json.object("stem","명반응의 주된 장소는?","topic","광합성","options",Json.array("틸라코이드 막","스트로마","핵막","세포벽","액포"),"answer",0,"explanation","명반응은 틸라코이드 막에서 일어난다.","option_explanations",Json.array("위치","다른 과정","핵","벽","공간"),"citations",Json.array(c))));}
    @Test public void citationsMustExistOnSelectedSourcePage() throws Exception {QuestionValidator.validate(result(),sources(),1,false);JSONObject missing=result();missing.getJSONArray("questions").getJSONObject(0).getJSONArray("citations").getJSONObject(0).put("source_id","invented");assertThrows(Exception.class,()->QuestionValidator.validate(missing,sources(),1,false));JSONObject wrongPage=result();wrongPage.getJSONArray("questions").getJSONObject(0).getJSONArray("citations").getJSONObject(0).put("page",99);assertThrows(Exception.class,()->QuestionValidator.validate(wrongPage,sources(),1,false));JSONObject quote=result();quote.getJSONArray("questions").getJSONObject(0).getJSONArray("citations").getJSONObject(0).put("quote","자료에 없는 인용문");assertThrows(Exception.class,()->QuestionValidator.validate(quote,sources(),1,false));}
    @Test public void duplicateChoicesAndAnswerLeaksRejected() throws Exception {JSONObject duplicate=result();duplicate.getJSONArray("questions").getJSONObject(0).getJSONArray("options").put(1,"틸라코이드 막");assertThrows(Exception.class,()->QuestionValidator.validate(duplicate,sources(),1,false));JSONObject badAnswer=result();badAnswer.getJSONArray("questions").getJSONObject(0).put("answer",5);assertThrows(Exception.class,()->QuestionValidator.validate(badAnswer,sources(),1,false));JSONObject leak=result();leak.getJSONArray("questions").getJSONObject(0).getJSONArray("options").put(0,"질문에 그대로 드러나면 쉽게 고르는 정답");leak.getJSONArray("questions").getJSONObject(0).put("stem","질문에 그대로 드러나면 쉽게 고르는 정답을 고르세요");assertThrows(Exception.class,()->QuestionValidator.validate(leak,sources(),1,false));}
    @Test public void originalQuestionsRequireAnAnswerKeySource() throws Exception {assertThrows(Exception.class,()->QuestionValidator.validate(result(),sources(),1,true));JSONObject original=result();original.getJSONArray("questions").getJSONObject(0).put("answer_citation",Json.object("source_id","s1","page",1,"quote","틸라코이드 막에서 ATP와 NADPH를 생성한다."));assertThrows(Exception.class,()->QuestionValidator.validate(original,sources(),1,true));JSONArray source=sources();source.getJSONObject(0).put("role","answerkey");QuestionValidator.validate(original,source,1,true);}
    @Test public void professorDirectionsCannotBeInventedFromTextbooks() throws Exception {JSONObject r=result();r.getJSONArray("directives").put(Json.object("kind","remember","text","외우세요","source_id","s1","page",1,"quote","틸라코이드 막에서 ATP와 NADPH를 생성한다."));assertThrows(Exception.class,()->QuestionValidator.validate(r,sources(),1,false));}
    @Test public void subscriptionRequestUsesRequiredPublicContract() throws Exception {JSONObject r=StudyGenerator.request("account-model","instructions",Json.array(Json.object("type","input_text","text","자료")));assertFalse(r.getBoolean("store"));assertTrue(r.getBoolean("stream"));assertEquals("account-model",r.getString("model"));assertFalse(r.has("background"));assertFalse(r.has("temperature"));assertFalse(r.has("max_output_tokens"));assertEquals("user",r.getJSONArray("input").getJSONObject(0).getString("role"));}
}
